import { Router } from 'express';
import { getDrivers, getDriverById, createDriver, updateDriver, deleteDriver, getDriverDocuments, verifyDriverDocument, } from '../controllers/driversController.js';
const router = Router();
router.get('/documents', getDriverDocuments);
router.post('/documents/:id/verify', verifyDriverDocument);
router.get('/', getDrivers);
router.get('/:id', getDriverById);
router.post('/', createDriver);
router.put('/:id', updateDriver);
router.delete('/:id', deleteDriver);
export default router;
